WITH latest AS (SELECT id, city, opened_date, sqft FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY city, region ORDER BY opened_date DESC, id) AS row_num FROM stores) t WHERE row_num = 1), enriched AS (SELECT id, city, opened_date, MAX(sqft) OVER (PARTITION BY city ORDER BY sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_sqft, SUM(sqft) OVER (PARTITION BY city ORDER BY sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_sqft, COUNT(sqft) OVER (PARTITION BY city ORDER BY sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_sqft FROM latest), scored AS (SELECT *, ROUND(running_max_sqft / SUM(running_max_sqft) OVER (PARTITION BY city), 4) AS running_max_sqft_share, SUM(running_max_sqft) OVER (PARTITION BY YEAR(opened_date), city) AS opened_date_year_sum_running_max_sqft, CUME_DIST() OVER (PARTITION BY city ORDER BY running_count_sqft DESC NULLS LAST) AS running_count_sqft_cume_dist, SUM(running_sum_sqft) OVER (PARTITION BY city ORDER BY running_sum_sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_running_sum_sqft, LAST_VALUE(running_max_sqft) IGNORE NULLS OVER (ORDER BY running_max_sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_running_max_sqft FROM enriched), with_last AS (SELECT s.id, s.city, s.opened_date, s.running_max_sqft, s.running_sum_sqft, s.running_count_sqft, s.running_count_sqft_cume_dist, s.cumulative_running_sum_sqft, top1.inventory_quantity, top1.last_restock FROM scored s LEFT JOIN LATERAL (SELECT c.quantity AS inventory_quantity, c.last_restock FROM inventory c WHERE c.store_id = s.id ORDER BY c.quantity DESC, c.id DESC LIMIT 1) top1 ON TRUE), scored_stores AS (SELECT id, running_sum_sqft, running_count_sqft, cumulative_running_sum_sqft, inventory_quantity, MIN(running_max_sqft) OVER (PARTITION BY city ORDER BY running_count_sqft_cume_dist, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_running_max_sqft, SUM(running_max_sqft) OVER (PARTITION BY city ORDER BY running_count_sqft_cume_dist, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_running_max_sqft, COUNT(running_max_sqft) OVER (PARTITION BY city ORDER BY running_count_sqft_cume_dist, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_running_max_sqft, MAX(running_max_sqft) OVER (PARTITION BY city ORDER BY running_count_sqft_cume_dist, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_running_max_sqft, ROW_NUMBER() OVER (ORDER BY running_count_sqft_cume_dist DESC, id) AS event_seq FROM with_last WHERE running_sum_sqft IS NOT NULL) SELECT CASE WHEN running_min_running_max_sqft >= 17100 THEN 'HIGH' ELSE 'LOW' END AS running_min_running_max_sqft_tier, CASE WHEN running_max_running_max_sqft >= 14100 THEN 'LARGE' ELSE 'SMALL' END AS running_max_running_max_sqft_tier, PERCENTILE_APPROX(running_min_running_max_sqft, 0.95) AS running_min_running_max_sqft_p95, APPROX_PERCENTILE(inventory_quantity, ARRAY(0.25, 0.5, 0.75)) AS inventory_quantity_quartiles, MAX(running_count_sqft) AS max_running_count_sqft, PERCENTILE_APPROX(event_seq, ARRAY(0.25, 0.5, 0.75)) AS event_seq_quartiles, AVG(event_seq) AS avg_event_seq, GROUPING_ID() AS gid FROM scored_stores GROUP BY GROUPING SETS ((CASE WHEN running_min_running_max_sqft >= 17100 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN running_max_running_max_sqft >= 14100 THEN 'LARGE' ELSE 'SMALL' END), (CASE WHEN running_min_running_max_sqft >= 17100 THEN 'HIGH' ELSE 'LOW' END), ()) ORDER BY running_max_running_max_sqft_tier DESC
